/**
 * Project Selector Dropdown
 * 
 * Hostinger-style dropdown for quickly switching between projects.
 * Shows current project with ability to switch to other projects.
 */

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Select, Avatar, Space, Typography, Spin, Input, Divider } from 'antd';
import { SearchOutlined, GlobalOutlined, CheckOutlined } from '@ant-design/icons';
import { useQuery } from '@tanstack/react-query';
import { api } from '@/lib/api';
import { useThemeStore } from '@/stores/theme';
import type { Project } from '@lsm/types';

const { Text } = Typography;

interface ProjectSelectorProps {
  currentProject: Project;
}

export function ProjectSelector({ currentProject }: ProjectSelectorProps) {
  const navigate = useNavigate();
  const { resolvedTheme } = useThemeStore();
  const isDark = resolvedTheme === 'dark';
  const [searchTerm, setSearchTerm] = useState('');
  const [isOpen, setIsOpen] = useState(false);

  // Fetch all projects for the dropdown
  const { data: projectsData, isLoading } = useQuery({
    queryKey: ['projects-list'],
    queryFn: () => api.projects.list({ per_page: 100 }).then(r => r.data.data),
    staleTime: 30000,
    enabled: isOpen, // Only fetch when dropdown is open
  });

  const projects = projectsData || [];
  const filteredProjects = projects.filter(
    (p: Project) => p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.url?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelect = (projectId: number) => {
    navigate(`/projects/${projectId}?section=overview`);
    setIsOpen(false);
    setSearchTerm('');
  };

  const cardStyle = {
    background: isDark ? '#0f172a' : '#fff',
    border: isDark ? '1px solid #334155' : '1px solid #e2e8f0',
    borderRadius: 8,
    padding: '8px 12px',
    cursor: 'pointer',
    transition: 'all 0.2s ease',
  };

  return (
    <div style={{ padding: '12px 12px 8px' }}>
      <Text 
        type="secondary" 
        style={{ 
          fontSize: 11, 
          textTransform: 'uppercase', 
          letterSpacing: '0.5px',
          display: 'block',
          marginBottom: 8,
          paddingLeft: 4,
        }}
      >
        Website name
      </Text>
      
      <Select
        open={isOpen}
        onDropdownVisibleChange={setIsOpen}
        style={{ width: '100%' }}
        value={currentProject.id}
        onChange={handleSelect}
        loading={isLoading}
        showSearch={false}
        popupMatchSelectWidth={280}
        dropdownStyle={{
          padding: 0,
          borderRadius: 12,
        }}
        labelRender={() => (
          <Space align="center" style={{ gap: 10 }}>
            <Avatar
              size={24}
              style={{
                background: isDark ? '#7c3aed' : '#f3e8ff',
                color: isDark ? '#fff' : '#7c3aed',
                fontSize: 12,
                fontWeight: 600,
              }}
            >
              {currentProject.name.charAt(0).toUpperCase()}
            </Avatar>
            <div style={{ overflow: 'hidden' }}>
              <Text strong style={{ fontSize: 13 }} ellipsis>
                {currentProject.url?.replace(/^https?:\/\//, '') || currentProject.name}
              </Text>
            </div>
          </Space>
        )}
        dropdownRender={() => (
          <div style={{ padding: 8 }}>
            {/* Search */}
            <Input
              placeholder="Search websites..."
              prefix={<SearchOutlined style={{ color: '#94a3b8' }} />}
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              style={{ marginBottom: 8 }}
              autoFocus
            />
            
            {/* Project List */}
            <div style={{ maxHeight: 300, overflowY: 'auto' }}>
              {isLoading ? (
                <div style={{ textAlign: 'center', padding: 20 }}>
                  <Spin size="small" />
                </div>
              ) : filteredProjects.length === 0 ? (
                <div style={{ textAlign: 'center', padding: 20 }}>
                  <Text type="secondary">No websites found</Text>
                </div>
              ) : (
                filteredProjects.map((project: Project) => (
                  <div
                    key={project.id}
                    onClick={() => handleSelect(project.id)}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: 10,
                      padding: '10px 12px',
                      borderRadius: 8,
                      cursor: 'pointer',
                      background: project.id === currentProject.id 
                        ? (isDark ? 'rgba(124, 58, 237, 0.2)' : 'rgba(124, 58, 237, 0.1)')
                        : 'transparent',
                      marginBottom: 4,
                      transition: 'background 0.15s',
                    }}
                    onMouseEnter={(e) => {
                      if (project.id !== currentProject.id) {
                        e.currentTarget.style.background = isDark ? '#1e293b' : '#f8fafc';
                      }
                    }}
                    onMouseLeave={(e) => {
                      if (project.id !== currentProject.id) {
                        e.currentTarget.style.background = 'transparent';
                      }
                    }}
                  >
                    <Avatar
                      size={28}
                      style={{
                        background: isDark ? '#7c3aed' : '#f3e8ff',
                        color: isDark ? '#fff' : '#7c3aed',
                        fontSize: 12,
                        fontWeight: 600,
                        flexShrink: 0,
                      }}
                    >
                      {project.name.charAt(0).toUpperCase()}
                    </Avatar>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <Text strong style={{ fontSize: 13, display: 'block' }} ellipsis>
                        {project.name}
                      </Text>
                      {project.url && (
                        <Text type="secondary" style={{ fontSize: 11 }} ellipsis>
                          {project.url.replace(/^https?:\/\//, '')}
                        </Text>
                      )}
                    </div>
                    {project.id === currentProject.id && (
                      <CheckOutlined style={{ color: '#7c3aed', fontSize: 14 }} />
                    )}
                  </div>
                ))
              )}
            </div>

            <Divider style={{ margin: '8px 0' }} />
            
            {/* Add Website */}
            <div
              onClick={() => navigate('/projects?action=new')}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 8,
                padding: '8px 12px',
                borderRadius: 8,
                cursor: 'pointer',
                color: '#7c3aed',
                fontWeight: 500,
                fontSize: 13,
              }}
            >
              <GlobalOutlined />
              Add Website
            </div>
          </div>
        )}
      />
    </div>
  );
}
