/**
 * Project Sub-Navigation Component V2
 * 
 * Hostinger-style navigation with:
 * - Project selector dropdown at top
 * - Collapsible menu groups with expand/collapse
 * - Icon + text labels
 * - Badges for counts
 */

import { useState } from 'react';
import { Menu, Badge, Typography } from 'antd';
import type { MenuProps } from 'antd';
import {
  DashboardOutlined,
  CloudOutlined,
  SettingOutlined,
  SafetyOutlined,
  BugOutlined,
  FileTextOutlined,
  AppstoreOutlined,
  PictureOutlined,
  CodeOutlined,
  DatabaseOutlined,
  CheckSquareOutlined,
  FileOutlined,
  RightOutlined,
  DownOutlined,
  RocketOutlined,
  ThunderboltOutlined,
  CopyOutlined,
  BookOutlined,
} from '@ant-design/icons';
import { useThemeStore } from '@/stores/theme';
import { ProjectSelector } from './ProjectSelector';
import type { Project } from '@lsm/types';

const { Text } = Typography;

type MenuItem = Required<MenuProps>['items'][number];

interface ProjectSubNavProps {
  project: Project;
  activeSection: string;
  onSectionChange: (section: string) => void;
  counts?: {
    plugins?: number;
    themes?: number;
    core?: number;
    backups?: number;
    vulnerabilities?: number;
    issues?: number;
    todos?: number;
    resources?: number;
  };
  hasRmbConnection?: boolean;
}

export function ProjectSubNav({
  project,
  activeSection,
  onSectionChange,
  counts = {},
  hasRmbConnection = false,
}: ProjectSubNavProps) {
  const { resolvedTheme } = useThemeStore();
  const isDark = resolvedTheme === 'dark';

  // Track which groups are expanded (like Hostinger)
  const [expandedGroups, setExpandedGroups] = useState<string[]>(['wordpress', 'project']);

  const toggleGroup = (key: string) => {
    setExpandedGroups(prev => 
      prev.includes(key) 
        ? prev.filter(k => k !== key)
        : [...prev, key]
    );
  };

  const groupHeaderStyle = {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: '12px 16px',
    cursor: 'pointer',
    borderRadius: 8,
    margin: '4px 8px',
    transition: 'background 0.15s',
  };

  const menuItems: MenuItem[] = [
    // Overview (always visible, no group)
    {
      key: 'overview',
      icon: <DashboardOutlined />,
      label: 'Overview',
    },
    // WordPress Group (collapsible like Hostinger)
    {
      key: 'wordpress-group',
      type: 'group',
      label: (
        <div 
          style={groupHeaderStyle}
          onClick={(e) => { e.stopPropagation(); toggleGroup('wordpress'); }}
          onMouseEnter={(e) => e.currentTarget.style.background = isDark ? '#1e293b' : '#f8fafc'}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          <span style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <SettingOutlined style={{ fontSize: 16, color: isDark ? '#94a3b8' : '#64748b' }} />
            <Text strong style={{ fontSize: 13 }}>WordPress</Text>
          </span>
          {expandedGroups.includes('wordpress') ? (
            <DownOutlined style={{ fontSize: 10, color: '#94a3b8' }} />
          ) : (
            <RightOutlined style={{ fontSize: 10, color: '#94a3b8' }} />
          )}
        </div>
      ),
      children: expandedGroups.includes('wordpress') ? [
        {
          key: 'wp-overview',
          label: 'Overview',
          disabled: !hasRmbConnection,
        },
        {
          key: 'security',
          label: 'Security',
          disabled: !hasRmbConnection,
        },
        {
          key: 'plugins',
          label: (
            <span style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
              Plugins
              {counts.plugins !== undefined && counts.plugins > 0 && (
                <Badge count={counts.plugins} size="small" style={{ backgroundColor: '#f59e0b' }} />
              )}
            </span>
          ),
          disabled: !hasRmbConnection,
        },
        {
          key: 'themes',
          label: (
            <span style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
              Themes
              {counts.themes !== undefined && counts.themes > 0 && (
                <Badge count={counts.themes} size="small" style={{ backgroundColor: '#f59e0b' }} />
              )}
            </span>
          ),
          disabled: !hasRmbConnection,
        },
        {
          key: 'backups',
          label: 'Backups',
          disabled: !hasRmbConnection,
        },
        {
          key: 'staging',
          label: 'Staging',
          disabled: true, // Coming soon
        },
        {
          key: 'issues',
          label: (
            <span style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
              PHP Errors
              {counts.issues !== undefined && counts.issues > 0 && (
                <Badge count={counts.issues} size="small" style={{ backgroundColor: '#ef4444' }} />
              )}
            </span>
          ),
          disabled: !hasRmbConnection,
        },
      ] : [],
    },
    // Performance Group
    {
      key: 'performance-group',
      type: 'group',
      label: (
        <div 
          style={groupHeaderStyle}
          onClick={(e) => { e.stopPropagation(); toggleGroup('performance'); }}
          onMouseEnter={(e) => e.currentTarget.style.background = isDark ? '#1e293b' : '#f8fafc'}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          <span style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <ThunderboltOutlined style={{ fontSize: 16, color: isDark ? '#94a3b8' : '#64748b' }} />
            <Text strong style={{ fontSize: 13 }}>Performance</Text>
          </span>
          {expandedGroups.includes('performance') ? (
            <DownOutlined style={{ fontSize: 10, color: '#94a3b8' }} />
          ) : (
            <RightOutlined style={{ fontSize: 10, color: '#94a3b8' }} />
          )}
        </div>
      ),
      children: expandedGroups.includes('performance') ? [
        {
          key: 'uptime',
          label: 'Uptime Monitoring',
        },
        {
          key: 'speed',
          label: 'Page Speed',
          disabled: true, // Coming soon
        },
      ] : [],
    },
    // Project Management Group  
    {
      key: 'project-group',
      type: 'group',
      label: (
        <div 
          style={groupHeaderStyle}
          onClick={(e) => { e.stopPropagation(); toggleGroup('project'); }}
          onMouseEnter={(e) => e.currentTarget.style.background = isDark ? '#1e293b' : '#f8fafc'}
          onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
        >
          <span style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <RocketOutlined style={{ fontSize: 16, color: isDark ? '#94a3b8' : '#64748b' }} />
            <Text strong style={{ fontSize: 13 }}>Project</Text>
          </span>
          {expandedGroups.includes('project') ? (
            <DownOutlined style={{ fontSize: 10, color: '#94a3b8' }} />
          ) : (
            <RightOutlined style={{ fontSize: 10, color: '#94a3b8' }} />
          )}
        </div>
      ),
      children: expandedGroups.includes('project') ? [
        {
          key: 'todos',
          label: (
            <span style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
              Todos
              {counts.todos !== undefined && counts.todos > 0 && (
                <Badge count={counts.todos} size="small" />
              )}
            </span>
          ),
        },
        {
          key: 'resources',
          label: (
            <span style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
              Resources
              {counts.resources !== undefined && counts.resources > 0 && (
                <Badge count={counts.resources} size="small" showZero={false} />
              )}
            </span>
          ),
        },
        {
          key: 'reports',
          label: 'Reports',
        },
        {
          key: 'support',
          label: 'Support Tickets',
        },
      ] : [],
    },
    // Settings (standalone)
    {
      key: 'settings',
      icon: <SettingOutlined />,
      label: 'Settings',
    },
  ];

  return (
    <div>
      {/* Project Selector Dropdown */}
      <ProjectSelector currentProject={project} />
      
      {/* Navigation Menu */}
      <Menu
        mode="inline"
        selectedKeys={[activeSection]}
        onClick={({ key }) => {
          // Only navigate if it's an actual section, not a group header
          if (!key.includes('-group')) {
            onSectionChange(key);
          }
        }}
        items={menuItems}
        style={{
          background: 'transparent',
          borderRight: 0,
        }}
        className="project-subnav"
      />
    </div>
  );
}
