/**
 * Issues Section - PHP Errors Monitoring Placeholder
 */

import { Empty, Typography, Card } from 'antd';
import { BugOutlined, CheckCircleOutlined } from '@ant-design/icons';
import { useThemeStore } from '@/stores/theme';

const { Text, Title } = Typography;

interface IssuesSectionProps {
  project: any;
}

export default function IssuesSection({ project }: IssuesSectionProps) {
  const { resolvedTheme } = useThemeStore();
  const isDark = resolvedTheme === 'dark';

  if (!project.health_check_secret) {
    return (
      <Empty
        image={<BugOutlined style={{ fontSize: 48, color: '#94a3b8' }} />}
        description={<Text type="secondary">Connect WordPress to monitor PHP errors</Text>}
      />
    );
  }

  return (
    <div style={{ padding: '24px 0' }}>
      <Title level={5}>PHP Errors Monitoring</Title>
      
      <Card
        style={{
          borderRadius: 12,
          background: isDark ? '#1e293b' : '#fff',
          textAlign: 'center',
          padding: 40,
        }}
      >
        <CheckCircleOutlined style={{ fontSize: 48, color: '#22c55e', marginBottom: 16 }} />
        <div>
          <Text strong style={{ fontSize: 16 }}>No PHP issues found</Text>
        </div>
        <Text type="secondary">PHP error monitoring coming soon.</Text>
      </Card>
    </div>
  );
}
