/**
 * Plugins Section - WP Umbrella Style
 * 
 * Features:
 * - Plugin table with security status, recommendations
 * - Active toggle (activate/deactivate)
 * - Auto-update toggle (enable/disable auto-updates)
 * - Update button with version info
 * - Bulk selection and actions
 * - Search functionality
 */

import { useState, useMemo } from 'react';
import {
  Table,
  Typography,
  Tag,
  Switch,
  Button,
  Input,
  Space,
  Tooltip,
  Empty,
  Alert,
  Badge,
  Dropdown,
  Popconfirm,
  App,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import type { MenuProps } from 'antd';
import {
  SearchOutlined,
  CheckCircleOutlined,
  ExclamationCircleOutlined,
  SyncOutlined,
  DeleteOutlined,
  DownOutlined,
  ReloadOutlined,
  AppstoreOutlined,
} from '@ant-design/icons';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '@/lib/api';
import { useThemeStore } from '@/stores/theme';

const { Text, Title, Link } = Typography;

interface Plugin {
  slug: string;
  name: string;
  version: string;
  new_version?: string;
  update_available: boolean;
  is_active: boolean;
  auto_update: boolean;
  vulnerability?: {
    severity: 'low' | 'medium' | 'high' | 'critical';
    description: string;
    link?: string;
  };
}

interface PluginsSectionProps {
  project: any;
}

// Mock data for development - will be replaced with real API data
const mockPlugins: Plugin[] = [
  {
    slug: 'woocommerce',
    name: 'WooCommerce',
    version: '8.5.0',
    new_version: '8.6.1',
    update_available: true,
    is_active: true,
    auto_update: false,
    vulnerability: {
      severity: 'medium',
      description: 'Cross-Site Scripting vulnerability in checkout',
      link: 'https://wpscan.com/vulnerability/123',
    },
  },
  {
    slug: 'advanced-custom-fields',
    name: 'Advanced Custom Fields',
    version: '6.6.2',
    new_version: '6.7.0',
    update_available: true,
    is_active: true,
    auto_update: true,
  },
  {
    slug: 'akismet',
    name: 'Akismet Anti-spam: Spam Protection',
    version: '5.5',
    new_version: '5.6',
    update_available: true,
    is_active: true,
    auto_update: true,
  },
  {
    slug: 'all-in-one-seo-pack',
    name: 'All in One SEO',
    version: '4.9.3',
    is_active: false,
    update_available: false,
    auto_update: false,
  },
  {
    slug: 'elementor',
    name: 'Elementor',
    version: '3.19.0',
    is_active: true,
    update_available: false,
    auto_update: true,
  },
  {
    slug: 'wpforms-lite',
    name: 'WPForms Lite',
    version: '1.8.6',
    new_version: '1.8.7',
    update_available: true,
    is_active: true,
    auto_update: false,
  },
];

export default function PluginsSection({ project }: PluginsSectionProps) {
  const { resolvedTheme } = useThemeStore();
  const isDark = resolvedTheme === 'dark';
  const { message } = App.useApp();
  const queryClient = useQueryClient();

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedRowKeys, setSelectedRowKeys] = useState<React.Key[]>([]);

  // Check if WordPress is connected
  const hasRmbConnection = !!project.health_check_secret;

  // Fetch plugins (using mock data for now)
  const { data: pluginsData, isLoading, refetch } = useQuery({
    queryKey: ['plugins', project.id],
    queryFn: async () => {
      // TODO: Replace with real API call
      // const response = await api.rmb.getPlugins(project.id);
      // return response.data;
      return mockPlugins;
    },
    enabled: hasRmbConnection,
    staleTime: 30000,
  });

  const plugins = pluginsData || [];

  // Filter plugins by search
  const filteredPlugins = useMemo(() => {
    if (!searchTerm) return plugins;
    const term = searchTerm.toLowerCase();
    return plugins.filter(
      (p: Plugin) =>
        p.name.toLowerCase().includes(term) ||
        p.slug.toLowerCase().includes(term)
    );
  }, [plugins, searchTerm]);

  // Update plugin mutation
  const updatePluginMutation = useMutation({
    mutationFn: async (pluginSlug: string) => {
      // TODO: Real API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      return { success: true };
    },
    onSuccess: () => {
      message.success('Plugin updated successfully');
      refetch();
    },
    onError: () => message.error('Failed to update plugin'),
  });

  // Toggle active mutation
  const toggleActiveMutation = useMutation({
    mutationFn: async ({ slug, active }: { slug: string; active: boolean }) => {
      // TODO: Real API call
      await new Promise(resolve => setTimeout(resolve, 500));
      return { success: true };
    },
    onSuccess: (_, { active }) => {
      message.success(`Plugin ${active ? 'activated' : 'deactivated'}`);
      refetch();
    },
    onError: () => message.error('Failed to toggle plugin'),
  });

  // Toggle auto-update mutation
  const toggleAutoUpdateMutation = useMutation({
    mutationFn: async ({ slug, enabled }: { slug: string; enabled: boolean }) => {
      // TODO: Real API call
      await new Promise(resolve => setTimeout(resolve, 500));
      return { success: true };
    },
    onSuccess: (_, { enabled }) => {
      message.success(`Auto-update ${enabled ? 'enabled' : 'disabled'}`);
      refetch();
    },
    onError: () => message.error('Failed to toggle auto-update'),
  });

  // Delete plugin mutation
  const deletePluginMutation = useMutation({
    mutationFn: async (pluginSlug: string) => {
      // TODO: Real API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      return { success: true };
    },
    onSuccess: () => {
      message.success('Plugin deleted');
      refetch();
    },
    onError: () => message.error('Failed to delete plugin'),
  });

  // Bulk actions
  const bulkActions: MenuProps['items'] = [
    {
      key: 'update',
      label: 'Update Selected',
      icon: <SyncOutlined />,
      onClick: () => message.info(`Updating ${selectedRowKeys.length} plugins...`),
    },
    {
      key: 'activate',
      label: 'Activate Selected',
      onClick: () => message.info(`Activating ${selectedRowKeys.length} plugins...`),
    },
    {
      key: 'deactivate',
      label: 'Deactivate Selected',
      onClick: () => message.info(`Deactivating ${selectedRowKeys.length} plugins...`),
    },
    {
      key: 'enable-autoupdate',
      label: 'Enable Auto-update',
      onClick: () => message.info(`Enabling auto-update for ${selectedRowKeys.length} plugins...`),
    },
    {
      key: 'disable-autoupdate',
      label: 'Disable Auto-update',
      onClick: () => message.info(`Disabling auto-update for ${selectedRowKeys.length} plugins...`),
    },
    { type: 'divider' },
    {
      key: 'delete',
      label: 'Delete Selected',
      icon: <DeleteOutlined />,
      danger: true,
      onClick: () => message.warning(`Delete ${selectedRowKeys.length} plugins...`),
    },
  ];

  // Table columns
  const columns: ColumnsType<Plugin> = [
    {
      title: 'Installed plugin',
      dataIndex: 'name',
      key: 'name',
      sorter: (a, b) => a.name.localeCompare(b.name),
      render: (name: string, record: Plugin) => (
        <div>
          <Text strong>{name}</Text>
          <div>
            <Text type="secondary" style={{ fontSize: 12 }}>
              Version {record.version}
            </Text>
          </div>
        </div>
      ),
    },
    {
      title: 'Security status',
      key: 'security',
      width: 180,
      sorter: (a, b) => (a.vulnerability ? 1 : 0) - (b.vulnerability ? 1 : 0),
      render: (_, record: Plugin) => {
        if (record.vulnerability) {
          const colors: Record<string, string> = {
            low: '#f59e0b',
            medium: '#f97316',
            high: '#ef4444',
            critical: '#dc2626',
          };
          return (
            <Space>
              <ExclamationCircleOutlined style={{ color: colors[record.vulnerability.severity] }} />
              <span>
                <Text type="danger">Vulnerability issue.</Text>
                {record.vulnerability.link && (
                  <Link href={record.vulnerability.link} target="_blank" style={{ marginLeft: 4 }}>
                    Learn more
                  </Link>
                )}
              </span>
            </Space>
          );
        }
        return (
          <Space>
            <CheckCircleOutlined style={{ color: '#22c55e' }} />
            <Text style={{ color: '#22c55e' }}>Secure</Text>
          </Space>
        );
      },
    },
    {
      title: 'Recommendation',
      key: 'recommendation',
      width: 150,
      render: (_, record: Plugin) => {
        if (record.vulnerability) {
          return <Text type="danger">Update to safe version</Text>;
        }
        if (record.update_available) {
          return <Text type="secondary">Update available</Text>;
        }
        return null;
      },
    },
    {
      title: 'Active',
      key: 'active',
      width: 80,
      align: 'center',
      render: (_, record: Plugin) => (
        <Switch
          checked={record.is_active}
          loading={toggleActiveMutation.isPending}
          onChange={(checked) =>
            toggleActiveMutation.mutate({ slug: record.slug, active: checked })
          }
          size="small"
        />
      ),
    },
    {
      title: (
        <Tooltip title="Automatically update plugins when new versions are released">
          <span>Auto-update</span>
        </Tooltip>
      ),
      key: 'auto_update',
      width: 100,
      align: 'center',
      render: (_, record: Plugin) => (
        <Switch
          checked={record.auto_update}
          loading={toggleAutoUpdateMutation.isPending}
          onChange={(checked) =>
            toggleAutoUpdateMutation.mutate({ slug: record.slug, enabled: checked })
          }
          size="small"
          disabled={!record.is_active}
        />
      ),
    },
    {
      title: '',
      key: 'actions',
      width: 140,
      align: 'right',
      render: (_, record: Plugin) => (
        <Space>
          {record.update_available && (
            <Button
              type={record.vulnerability ? 'primary' : 'default'}
              size="small"
              loading={updatePluginMutation.isPending}
              onClick={() => updatePluginMutation.mutate(record.slug)}
            >
              Update
            </Button>
          )}
          <Popconfirm
            title="Delete plugin?"
            description="This will permanently remove the plugin from your site."
            onConfirm={() => deletePluginMutation.mutate(record.slug)}
            okText="Delete"
            okButtonProps={{ danger: true }}
          >
            <Button
              type="text"
              danger
              icon={<DeleteOutlined />}
              size="small"
              loading={deletePluginMutation.isPending}
            />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  // Show empty state if not connected
  if (!hasRmbConnection) {
    return (
      <Empty
        image={<AppstoreOutlined style={{ fontSize: 48, color: '#94a3b8' }} />}
        description={
          <Text type="secondary">
            Connect WordPress to manage plugins remotely
          </Text>
        }
      />
    );
  }

  // Count updates available and vulnerabilities
  const updatesCount = plugins.filter((p: Plugin) => p.update_available).length;
  const vulnerabilitiesCount = plugins.filter((p: Plugin) => p.vulnerability).length;

  return (
    <div style={{ padding: '24px 0' }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
        <Title level={5} style={{ margin: 0 }}>Installed plugins</Title>
        <Button icon={<ReloadOutlined />} onClick={() => refetch()} loading={isLoading}>
          Refresh
        </Button>
      </div>

      {/* Alerts */}
      {vulnerabilitiesCount > 0 && (
        <Alert
          type="error"
          message={`${vulnerabilitiesCount} plugin${vulnerabilitiesCount > 1 ? 's have' : ' has'} security vulnerabilities`}
          description="Update these plugins immediately to protect your site."
          style={{ marginBottom: 16 }}
          showIcon
        />
      )}

      {updatesCount > 0 && vulnerabilitiesCount === 0 && (
        <Alert
          type="info"
          message={`${updatesCount} update${updatesCount > 1 ? 's' : ''} available`}
          style={{ marginBottom: 16 }}
          showIcon
        />
      )}

      {/* Search and Bulk Actions */}
      <div style={{ display: 'flex', gap: 12, marginBottom: 16 }}>
        <Input
          placeholder="Search plugins..."
          prefix={<SearchOutlined style={{ color: '#94a3b8' }} />}
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ maxWidth: 300 }}
          allowClear
        />
        {selectedRowKeys.length > 0 && (
          <Dropdown menu={{ items: bulkActions }} trigger={['click']}>
            <Button>
              Bulk Actions ({selectedRowKeys.length}) <DownOutlined />
            </Button>
          </Dropdown>
        )}
      </div>

      {/* Table */}
      <Table
        rowSelection={{
          selectedRowKeys,
          onChange: setSelectedRowKeys,
        }}
        columns={columns}
        dataSource={filteredPlugins}
        rowKey="slug"
        loading={isLoading}
        pagination={false}
        size="middle"
        style={{
          background: isDark ? '#0f172a' : '#fff',
          borderRadius: 12,
          overflow: 'hidden',
        }}
      />
    </div>
  );
}
