/**
 * Security Section - Placeholder
 */

import { Empty, Typography, Card, Button, Alert } from 'antd';
import { SafetyOutlined } from '@ant-design/icons';
import { useThemeStore } from '@/stores/theme';

const { Text, Title } = Typography;

interface SecuritySectionProps {
  project: any;
}

export default function SecuritySection({ project }: SecuritySectionProps) {
  const { resolvedTheme } = useThemeStore();
  const isDark = resolvedTheme === 'dark';

  if (!project.health_check_secret) {
    return (
      <Empty
        image={<SafetyOutlined style={{ fontSize: 48, color: '#94a3b8' }} />}
        description={<Text type="secondary">Connect WordPress to enable security scanning</Text>}
      />
    );
  }

  return (
    <div style={{ padding: '24px 0' }}>
      <Title level={5}>Vulnerability Monitoring</Title>
      
      <Alert
        type="info"
        message="Security scanning coming soon"
        description="This section will show plugin vulnerabilities, security recommendations, and hardening options."
        style={{ marginBottom: 24 }}
      />

      <Button type="primary" disabled>Scan Website</Button>
    </div>
  );
}
