/**
 * Backups Section - Placeholder
 */

import { Empty, Typography, Button } from 'antd';
import { DatabaseOutlined } from '@ant-design/icons';

const { Text } = Typography;

interface BackupsSectionProps {
  project: any;
}

export default function BackupsSection({ project }: BackupsSectionProps) {
  if (!project.health_check_secret) {
    return (
      <Empty
        image={<DatabaseOutlined style={{ fontSize: 48, color: '#94a3b8' }} />}
        description={<Text type="secondary">Connect WordPress to enable backups</Text>}
      />
    );
  }

  return (
    <div style={{ padding: '24px 0' }}>
      <Button type="primary" disabled>Create Manual Backup</Button>
      <div style={{ marginTop: 16 }}>
        <Text type="secondary">Backup management coming soon.</Text>
      </div>
    </div>
  );
}
